"use client";

import Image from "next/image";
import { useEffect, useRef, useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { Button } from "@/components/ui/Button";
import { StepProgress } from "@/components/ui/StepProgress";
import { LocationPicker } from "@/components/map/LocationPicker";
import { searchAddress, type AddressSuggestion } from "@/lib/maps/forward-geocode";
import { getInitData, useTelegramViewportHeight } from "@/lib/telegram/webapp-client";
import { useVisualViewportHeight } from "@/lib/hooks/use-visual-viewport-height";
import { useLockBodyScroll } from "@/lib/hooks/use-lock-body-scroll";

interface Category {
  id: string;
  slug: string;
  name: string;
  emoji: string | null;
}
interface TrainingType {
  id: string;
  slug: string;
  name: string;
  emoji: string | null;
}

type Step =
  | "category"
  | "trainingType"
  | "businessTitle"
  | "where"
  | "when"
  | "time"
  | "seats"
  | "cost"
  | "businessCost"
  | "chat"
  | "details"
  | "review";

const DATE_PRESETS = [
  { label: "Сегодня", offsetDays: 0 },
  { label: "Завтра", offsetDays: 1 },
];

// 3D-иконки категорий МЕСТО — тот же комплект, что на главном экране и в карточках встреч.
const CATEGORY_ICON: Record<string, string> = {
  training: "/brand/3d/workout.png",
  cinema: "/brand/3d/movie.png",
  coffee: "/brand/3d/coffee.png",
  breakfast: "/brand/3d/breakfast.png",
  dinner: "/brand/3d/dinner.png",
  walk: "/brand/3d/walk.png",
  custom: "/brand/3d/custom-proposal.png",
};

// Компактный размер полей — весь шаг (включая карту и кнопку "Далее")
// должен помещаться на экране телефона без прокрутки страницы.
// min-w-0 + box-border обязательны: без них нативные <input type="date">
// и <input type="time"> на iOS игнорируют w-full и вылезают за край экрана
// (у flex-элементов по умолчанию min-width:auto, из-за чего браузер не
// сжимает их внутреннюю "родную" ширину до ширины контейнера).
const inputClass =
  "block w-full max-w-full min-w-0 box-border rounded-card border border-lavender-200 bg-white px-4 py-3 text-base text-ink-900 outline-none focus:border-accent";

export function CreateEventWizard() {
  const router = useRouter();
  useLockBodyScroll();
  const searchParams = useSearchParams();
  const preselectedCategory = searchParams.get("category");
  const preselectedTrainingType = searchParams.get("type");
  // "Для бизнеса" (см. кнопка на главном экране) — отдельная ветка мастера:
  // без готовых категорий, свой шаг про расходы (билет/бесплатно/свои
  // условия), свой лимит на размер группы и явный выбор "создавать чат?".
  const isBusiness = searchParams.get("business") === "true";
  const telegramViewportHeight = useTelegramViewportHeight();
  const visualViewportHeight = useVisualViewportHeight();
  const liveHeight = visualViewportHeight ?? telegramViewportHeight;

  const [categories, setCategories] = useState<Category[]>([]);
  const [trainingTypes, setTrainingTypes] = useState<TrainingType[]>([]);

  const [stepIndex, setStepIndex] = useState(0);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [categorySlug, setCategorySlug] = useState<string | null>(preselectedCategory);
  const [trainingTypeSlug, setTrainingTypeSlug] = useState<string | null>(preselectedTrainingType);
  const [placeName, setPlaceName] = useState("");  const [address, setAddress] = useState("");
  const [latitude, setLatitude] = useState<number | undefined>();
  const [longitude, setLongitude] = useState<number | undefined>();
  const [addressSuggestions, setAddressSuggestions] = useState<AddressSuggestion[]>([]);
  const [pickedFromAddress, setPickedFromAddress] = useState<{ latitude: number; longitude: number } | null>(null);
  // true сразу после того, как адрес выставлен программно (обратное
  // геокодирование по клику на карте или выбор подсказки) — тогда не надо
  // запускать поиск подсказок заново, это привело бы к бесконечному циклу.
  const suppressAddressSearchRef = useRef(false);

  // Карта на шаге "Где?" — пока не введено название места, чуть компактнее;
  // как только оно появляется, карта расширяется (шире и выше) и
  // открывается поле адреса — по явному запросу пользователя: сначала
  // называешь место, потом уже точный адрес и увеличенная карта для точной
  // отметки.
  const mapHeight = liveHeight
    ? Math.round(liveHeight * (placeName.trim().length > 0 ? 0.58 : 0.34))
    : placeName.trim().length > 0
      ? 360
      : 220;

  useEffect(() => {
    if (suppressAddressSearchRef.current) {
      suppressAddressSearchRef.current = false;
      return;
    }
    if (address.trim().length < 3) {
      setAddressSuggestions([]);
      return;
    }
    const timeout = setTimeout(() => {
      searchAddress(address).then(setAddressSuggestions);
    }, 400);
    return () => clearTimeout(timeout);
  }, [address]);

  function handlePickAddressSuggestion(s: AddressSuggestion) {
    suppressAddressSearchRef.current = true;
    setAddress(s.address);
    setLatitude(s.latitude);
    setLongitude(s.longitude);
    setPickedFromAddress({ latitude: s.latitude, longitude: s.longitude });
    setAddressSuggestions([]);
  }
  const [eventDate, setEventDate] = useState("");
  const [eventTime, setEventTime] = useState("");
  const [eventEndTime, setEventEndTime] = useState("");
  const [seatsTotal, setSeatsTotal] = useState(4);
  const [costType, setCostType] = useState<"each_pays" | "organizer_treats" | "free" | "negotiable">("each_pays");
  const [businessPricingType, setBusinessPricingType] = useState<"ticket" | "free" | "custom" | null>(null);
  const [businessTicketPrice, setBusinessTicketPrice] = useState("");
  const [businessCustomTerms, setBusinessCustomTerms] = useState("");
  // Чат — явный выбор организатора для "Для бизнеса", доступен только при
  // небольшой группе (см. ТЗ: "не больше 20 человек"). Для обычных встреч
  // чат создаётся всегда (это состояние тогда просто не используется).
  const [wantsChat, setWantsChat] = useState(true);
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");

  useEffect(() => {
    fetch("/api/categories")
      .then((r) => r.json())
      .then((data) => {
        setCategories(data.categories ?? []);
        setTrainingTypes(data.trainingTypes ?? []);
      });
  }, []);

  const steps: Step[] = isBusiness
    ? [
        "businessTitle",
        "where",
        "when",
        "time",
        "seats",
        "businessCost",
        ...(seatsTotal <= 20 ? (["chat"] as Step[]) : []),
        "details",
        "review",
      ]
    : categorySlug === "training"
      ? ["category", "trainingType", "where", "when", "time", "seats", "cost", "details", "review"]
      : ["category", "where", "when", "time", "seats", "cost", "details", "review"];

  const step = steps[stepIndex];
  const isLastStep = stepIndex === steps.length - 1;

  function goNext() {
    setError(null);
    if (stepIndex < steps.length - 1) setStepIndex(stepIndex + 1);
  }
  function goBack() {
    setError(null);
    if (stepIndex > 0) setStepIndex(stepIndex - 1);
  }

  function pickDatePreset(offsetDays: number) {
    const date = new Date();
    date.setDate(date.getDate() + offsetDays);
    setEventDate(date.toISOString().slice(0, 10));
  }

  async function handlePublish() {
    setSubmitting(true);
    setError(null);

    const initData = getInitData();
    if (!initData) {
      setError("Открой приложение через Telegram.");
      setSubmitting(false);
      return;
    }

    try {
      const res = await fetch("/api/events", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          categorySlug: isBusiness ? undefined : categorySlug,
          trainingTypeSlug: trainingTypeSlug ?? undefined,
          placeName,
          address,
          latitude,
          longitude,
          eventDate,
          eventTime,
          eventEndTime,
          seatsTotal,
          costType: isBusiness
            ? businessPricingType === "free"
              ? "free"
              : businessPricingType === "ticket"
                ? "each_pays"
                : "negotiable"
            : costType,
          title,
          description,
          isBusiness,
          businessPricingType: isBusiness ? businessPricingType ?? undefined : undefined,
          businessPricingDetails: isBusiness
            ? businessPricingType === "ticket"
              ? businessTicketPrice
              : businessPricingType === "custom"
                ? businessCustomTerms
                : undefined
            : undefined,
          hasChat: isBusiness ? wantsChat : undefined,
        }),
      });

      const data = await res.json();

      if (!res.ok) {
        if (data.error === "subscription_required") {
          setError("Нужна активная подписка.");
        } else if (data.error === "events_limit_reached") {
          setError("Лимит встреч по твоему тарифу исчерпан на этот период.");
        } else if (data.error === "group_size_exceeds_plan") {
          setError(`Твой тариф позволяет группу максимум из ${data.groupMax} человек.`);
        } else {
          setError("Не получилось опубликовать встречу.");
        }
        setSubmitting(false);
        return;
      }

      router.push(`/events/${data.eventId}/applications`);
    } catch {
      setError("Проблема с соединением.");
      setSubmitting(false);
    }
  }

  const canGoNext =
    (step === "category" && categorySlug !== null) ||
    (step === "trainingType" && trainingTypeSlug !== null) ||
    (step === "businessTitle" && title.trim().length >= 3) ||
    (step === "where" && placeName.trim().length >= 2 && latitude !== undefined && longitude !== undefined) ||
    (step === "when" && eventDate.length > 0) ||
    (step === "time" && eventTime.length > 0 && eventEndTime.length > 0 && eventEndTime > eventTime) ||
    (step === "seats" && seatsTotal >= 1) ||
    step === "cost" ||
    (step === "businessCost" &&
      businessPricingType !== null &&
      (businessPricingType !== "ticket" || businessTicketPrice.trim().length > 0) &&
      (businessPricingType !== "custom" || businessCustomTerms.trim().length > 0)) ||
    step === "chat" ||
    (step === "details" && (isBusiness || title.trim().length >= 3));

  return (
    <div
      className="fixed inset-0 z-50 flex flex-col overflow-hidden bg-background px-5 pt-4"
      style={{ height: liveHeight ? `${liveHeight}px` : "100dvh" }}
    >
      <StepProgress currentStep={stepIndex + 1} totalSteps={steps.length} />

      {/* min-h-0 обязателен, чтобы flex-child мог сжиматься и включать
          свою собственную прокрутку вместо раздувания всей страницы.
          pb-24 — запас снизу под кнопки, которые теперь настоящий fixed-
          футер (см. ниже), а не последний элемент этого же потока — иначе
          он не всегда оказывался прижат к самому низу экрана. */}
      {/* overflow-x-hidden — обязателен. Шаг "Где?" временно расширяет карту
          за пределы обычных отступов (-mx-5, см. ниже) — без явного запрета
          горизонтальной прокрутки здесь браузер мог "запомнить" сдвинутую
          вбок позицию скролла и перенести её на следующие шаги, из-за чего
          обычные поля (дата, время) визуально уезжали за правый край экрана. */}
      <div className="flex min-h-0 min-w-0 flex-1 flex-col justify-start gap-3 overflow-x-hidden overflow-y-auto py-3 pb-24">
        {step === "category" && (
          <StepBlock title="Что планируем?">
            <div className="grid grid-cols-2 gap-3">
              {categories.map((c) => {
                const icon = CATEGORY_ICON[c.slug];
                const selected = categorySlug === c.slug;
                return (
                  <button
                    key={c.id}
                    onClick={() => {
                      setCategorySlug(c.slug);
                      setTrainingTypeSlug(null);
                    }}
                    className={`flex flex-col items-start gap-2 rounded-card p-4 text-left text-sm font-medium transition ${
                      selected ? "bg-brand-gradient text-white shadow-cta" : "bg-white text-ink-900 shadow-card"
                    }`}
                  >
                    {icon ? (
                      <div className="relative h-11 w-11">
                        <Image src={icon} alt="" fill className="object-contain" sizes="44px" />
                      </div>
                    ) : (
                      <span className="text-2xl">{c.emoji}</span>
                    )}
                    {c.name}
                  </button>
                );
              })}
            </div>
          </StepBlock>
        )}

        {step === "trainingType" && (
          <StepBlock title="Какая тренировка?">
            <div className="grid grid-cols-2 gap-2">
              {trainingTypes.map((t) => (
                <button
                  key={t.id}
                  onClick={() => setTrainingTypeSlug(t.slug)}
                  className={`flex items-center gap-2 rounded-card p-3 text-left text-sm font-medium transition ${
                    trainingTypeSlug === t.slug ? "bg-brand-gradient text-white shadow-cta" : "bg-white text-ink-900 shadow-card"
                  }`}
                >
                  <span className="text-xl">{t.emoji}</span>
                  {t.name}
                </button>
              ))}
            </div>
          </StepBlock>
        )}

        {step === "businessTitle" && (
          <StepBlock title="Какое событие планируете создать?" subtitle="Название того, что вы организуете — концерт, дегустация, мастер-класс и т.д.">
            <input
              autoFocus
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="Например: Дегустация вин от сомелье"
              maxLength={100}
              className={inputClass}
            />
          </StepBlock>
        )}

        {step === "where" && (
          <StepBlock title="Где?" subtitle="Впиши название места и отметь точку на карте — адрес определится сам.">
            <input
              autoFocus
              value={placeName}
              onChange={(e) => setPlaceName(e.target.value)}
              placeholder="Название места"
              className={`mb-2 ${inputClass}`}
            />
            <div className="relative mb-2">
              {placeName.trim().length > 0 && (
                <>
                  <input
                    value={address}
                    onChange={(e) => setAddress(e.target.value)}
                    placeholder="Адрес — впиши сам или отметь точку на карте"
                    className={`text-base ${inputClass}`}
                  />
                  {addressSuggestions.length > 0 && (
                    <div className="absolute left-0 right-0 top-full z-10 mt-1 overflow-hidden rounded-card bg-white shadow-card-lg">
                      {addressSuggestions.map((s) => (
                        <button
                          key={s.address}
                          type="button"
                          onMouseDown={() => handlePickAddressSuggestion(s)}
                          className="block w-full border-b border-lavender-100 px-4 py-2.5 text-left text-sm text-ink-900 last:border-0 hover:bg-lavender-50"
                        >
                          {s.address}
                        </button>
                      ))}
                    </div>
                  )}
                </>
              )}
            </div>
            <LocationPicker
              onPick={({ latitude, longitude }) => {
                setLatitude(latitude);
                setLongitude(longitude);
              }}
              onAddressResolved={(resolved) => {
                suppressAddressSearchRef.current = true;
                setAddress(resolved);
              }}
              externalCoords={pickedFromAddress}
              heightPx={mapHeight}
            />
            {placeName.trim().length >= 2 && latitude === undefined && (
              <p className="mt-2 shrink-0 text-center text-xs font-medium text-accent">
                Отметь точку на карте, чтобы продолжить
              </p>
            )}
          </StepBlock>
        )}

        {step === "when" && (
          <StepBlock title="Когда?">
            <div className="mb-3 flex gap-2">
              {DATE_PRESETS.map((preset) => (
                <button
                  key={preset.label}
                  onClick={() => pickDatePreset(preset.offsetDays)}
                  className="flex-1 rounded-card bg-white p-3 text-sm font-medium text-ink-900 shadow-card"
                >
                  {preset.label}
                </button>
              ))}
            </div>
            <input
              type="date"
              value={eventDate}
              onChange={(e) => setEventDate(e.target.value)}
              min={new Date().toISOString().slice(0, 10)}
              className={`${inputClass} h-[52px] appearance-none text-center`}
            />
          </StepBlock>
        )}

        {step === "time" && (
          <StepBlock title="Во сколько?" subtitle="Точное время начала и окончания — по нему встреча автоматически завершится и закроется чат.">
            <div className="flex items-center gap-3">
              <div className="min-w-0 flex-1">
                <label className="mb-1 block text-xs font-medium text-ink-600">Начало</label>
                <input
                  type="time"
                  value={eventTime}
                  onChange={(e) => setEventTime(e.target.value)}
                  className={`${inputClass} h-[52px] appearance-none text-center`}
                />
              </div>
              <div className="min-w-0 flex-1">
                <label className="mb-1 block text-xs font-medium text-ink-600">Окончание</label>
                <input
                  type="time"
                  value={eventEndTime}
                  onChange={(e) => setEventEndTime(e.target.value)}
                  className={`${inputClass} h-[52px] appearance-none text-center`}
                />
              </div>
            </div>
            {eventTime && eventEndTime && eventEndTime <= eventTime && (
              <p className="mt-2 text-sm text-red-600">Время окончания должно быть позже начала.</p>
            )}
          </StepBlock>
        )}

        {step === "seats" && (
          <StepBlock title="Сколько человек нужно?">
            <div className="flex items-center justify-center gap-6">
              <button
                onClick={() => setSeatsTotal((n) => Math.max(1, n - 1))}
                className="flex h-12 w-12 items-center justify-center rounded-full bg-white text-xl text-accent shadow-card active:scale-95"
              >
                −
              </button>
              <span className="text-display w-12 text-center">{seatsTotal}</span>
              <button
                onClick={() => setSeatsTotal((n) => Math.min(isBusiness ? 500 : 30, n + 1))}
                className="flex h-12 w-12 items-center justify-center rounded-full bg-white text-xl text-accent shadow-card active:scale-95"
              >
                +
              </button>
            </div>
            {isBusiness && seatsTotal > 20 && (
              <p className="mt-3 text-center text-xs text-ink-600">
                При группе больше 20 человек общий чат не создаётся — люди будут откликаться напрямую.
              </p>
            )}
          </StepBlock>
        )}

        {step === "businessCost" && (
          <StepBlock title="Как насчёт расходов?">
            <div className="flex flex-col gap-2">
              {(
                [
                  ["ticket", "По билетам"],
                  ["free", "Бесплатно"],
                  ["custom", "Другие условия"],
                ] as const
              ).map(([value, label]) => (
                <button
                  key={value}
                  onClick={() => setBusinessPricingType(value)}
                  className={`rounded-card p-4 text-left text-sm font-medium transition ${
                    businessPricingType === value ? "bg-brand-gradient text-white shadow-cta" : "bg-white text-ink-900 shadow-card"
                  }`}
                >
                  {label}
                </button>
              ))}
            </div>
            {businessPricingType === "ticket" && (
              <input
                autoFocus
                value={businessTicketPrice}
                onChange={(e) => setBusinessTicketPrice(e.target.value)}
                placeholder="Например: 1500 ₽"
                maxLength={50}
                className={`mt-3 ${inputClass}`}
              />
            )}
            {businessPricingType === "custom" && (
              <textarea
                autoFocus
                value={businessCustomTerms}
                onChange={(e) => setBusinessCustomTerms(e.target.value)}
                placeholder="Опиши условия — что и как оплачивается"
                maxLength={300}
                rows={3}
                className={`mt-3 resize-none text-base ${inputClass}`}
              />
            )}
          </StepBlock>
        )}

        {step === "chat" && (
          <StepBlock title="Создавать чат?" subtitle="Общий чат для всех, кого примут на событие — можно списаться до встречи.">
            <div className="flex flex-col gap-2">
              <button
                onClick={() => setWantsChat(true)}
                className={`rounded-card p-4 text-left text-sm font-medium transition ${
                  wantsChat ? "bg-brand-gradient text-white shadow-cta" : "bg-white text-ink-900 shadow-card"
                }`}
              >
                Да, создать чат
              </button>
              <button
                onClick={() => setWantsChat(false)}
                className={`rounded-card p-4 text-left text-sm font-medium transition ${
                  !wantsChat ? "bg-brand-gradient text-white shadow-cta" : "bg-white text-ink-900 shadow-card"
                }`}
              >
                Нет, без чата — только заявки
              </button>
            </div>
            {!wantsChat && (
              <p className="mt-3 text-center text-xs text-ink-600">
                Люди будут откликаться на событие, ты увидишь заявки прямо в нём и получишь уведомление.
              </p>
            )}
          </StepBlock>
        )}

        {step === "cost" && (
          <StepBlock title="Как насчёт расходов?">
            <div className="flex flex-col gap-2">
              {(
                [
                  ["each_pays", "Каждый за себя"],
                  ["organizer_treats", "Автор угощает"],
                  ["free", "Без расходов"],
                  ["negotiable", "По договорённости"],
                ] as const
              ).map(([value, label]) => (
                <button
                  key={value}
                  onClick={() => setCostType(value)}
                  className={`rounded-card p-4 text-left text-sm font-medium transition ${
                    costType === value ? "bg-brand-gradient text-white shadow-cta" : "bg-white text-ink-900 shadow-card"
                  }`}
                >
                  {label}
                </button>
              ))}
            </div>
          </StepBlock>
        )}

        {step === "details" && (
          <StepBlock title={isBusiness ? "Описание" : "Название и описание"}>
            {!isBusiness && (
              <input
                autoFocus
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                placeholder="Например: Утренняя пробежка в парке"
                maxLength={100}
                className={`mb-2 ${inputClass}`}
              />
            )}
            <textarea
              autoFocus={isBusiness}
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="Короткое описание (необязательно)"
              maxLength={500}
              rows={3}
              className={`resize-none text-base ${inputClass}`}
            />
          </StepBlock>
        )}

        {step === "review" && (
          <StepBlock title="Всё верно?">
            <div className="space-y-2 rounded-card-lg bg-white p-5 shadow-card-lg">
              <ReviewRow label="Название" value={title} />
              <ReviewRow label="Место" value={placeName} />
              <ReviewRow label="Дата" value={eventDate} />
              <ReviewRow label="Время" value={`${eventTime}–${eventEndTime}`} />
              <ReviewRow label="Участников" value={String(seatsTotal)} />
              {isBusiness ? (
                <>
                  <ReviewRow
                    label="Расходы"
                    value={
                      businessPricingType === "ticket"
                        ? `Билет: ${businessTicketPrice}`
                        : businessPricingType === "custom"
                          ? businessCustomTerms
                          : "Бесплатно"
                    }
                  />
                  {seatsTotal <= 20 && <ReviewRow label="Чат" value={wantsChat ? "Создаётся" : "Без чата"} />}
                </>
              ) : (
                <ReviewRow
                  label="Расходы"
                  value={
                    { each_pays: "Каждый за себя", organizer_treats: "Автор угощает", free: "Без расходов", negotiable: "По договорённости" }[
                      costType
                    ]
                  }
                />
              )}
              {description && <ReviewRow label="Описание" value={description} />}
            </div>
          </StepBlock>
        )}

        {error && <p className="text-center text-sm text-red-600">{error}</p>}
      </div>

      <div className="absolute inset-x-0 bottom-0 flex shrink-0 gap-3 bg-background px-5 pb-3 pt-2">
        {stepIndex > 0 && (
          <Button variant="secondary" onClick={goBack} className="w-auto px-6">
            Назад
          </Button>
        )}
        {!isLastStep ? (
          <Button onClick={goNext} disabled={!canGoNext}>
            Далее
          </Button>
        ) : (
          <Button onClick={handlePublish} disabled={submitting}>
            {submitting ? "Публикуем..." : "Опубликовать"}
          </Button>
        )}
      </div>
    </div>
  );
}

function StepBlock({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="flex min-h-0 min-w-0 flex-1 flex-col space-y-3">
      <div className="shrink-0 text-center">
        <h1 className="text-title">{title}</h1>
        {subtitle && <p className="mt-1 text-xs text-ink-600">{subtitle}</p>}
      </div>
      <div className="flex min-h-0 min-w-0 flex-1 flex-col">{children}</div>
    </div>
  );
}

function ReviewRow({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex justify-between gap-4 text-sm">
      <span className="text-ink-600">{label}</span>
      <span className="text-right font-medium text-ink-900">{value}</span>
    </div>
  );
}
ENDOFFILE

mkdir -p "components/map"
cat > "components/map/EventsMap.tsx" << 'ENDOFFILE'
"use client";

import { forwardRef, useEffect, useImperativeHandle, useRef } from "react";
import { loadYandexMaps } from "@/lib/maps/load-yandex-maps";
import { searchAddress } from "@/lib/maps/forward-geocode";

export interface MapEventItem {
  id: string;
  title: string;
  eventDate: string;
  eventTime: string;
  latitude: number;
  longitude: number;
  placeName: string | null;
  address: string | null;
  seatsLeft: number;
  category: { slug: string; name: string; emoji: string | null } | null;
  isBusiness?: boolean;
}

export interface EventsMapHandle {
  /** Приближает карту так, чтобы в кадре поместились все переданные точки. */
  fitBounds: (points: [number, number][]) => void;
}

interface EventsMapProps {
  events: MapEventItem[];
  onSelect: (events: MapEventItem[]) => void;
  /**
   * Город из фильтра — карта переезжает туда, даже если в этом городе
   * пока нет ни одной встречи (раньше в таком случае карта оставалась на
   * запасном центре — Тюмени — независимо от выбранного города).
   */
  city?: string;
}

const DEFAULT_CENTER: [number, number] = [65.534328, 57.152985]; // Тюмень, запасной центр
// Пиксельный радиус группировки — ориентир из задания на кластеризацию
// (не радиус географического поиска, а расстояние на экране в CSS-пикселях).
const CLUSTER_GRID_SIZE = 60;
// Точность округления координат, чтобы найти встречи в буквально одной
// точке (например, две встречи в одном и том же месте, выбранном через
// автодополнение адреса) — 6 знаков после запятой ≈ 0.1м, ловит только
// настоящие совпадения, не "рядом, но другое здание".
const EXACT_MATCH_PRECISION = 6;
// На сколько метров технически "раздвигаем" встречи с одинаковыми
// координатами по кругу вокруг общей точки. Маленькое смещение —
// на обычном масштабе карты (город, район) это меньше одного экранного
// пикселя, поэтому такие встречи по-прежнему видны одним кружком; но при
// максимальном увеличении карты то же самое расстояние в метрах
// превращается в десятки экранных пикселей — больше порога кластеризации
// (CLUSTER_GRID_SIZE) — и стандартная пиксельная кластеризация сама
// естественно разводит их на отдельные значки. Раньше вместо этого
// применялось "жёсткое" объединение без раздвижения — по итогам
// тестирования пользователь явно попросил именно раздвигать при
// увеличении, а не держать одним кружком навсегда.
const JITTER_METERS = 4;
const METERS_PER_DEGREE_LAT = 111320;

/** Координаты центра города через геокодер — с фолбэком на Тюмень, если геокодирование не удалось. */
async function geocodeCityCenter(city: string): Promise<[number, number]> {
  const suggestions = await searchAddress(city);
  const first = suggestions[0];
  return first ? [first.longitude, first.latitude] : DEFAULT_CENTER;
}

// Новые SVG-маркеры (viewBox 256×288, "кончик" пина на y≈269/288). Соответствие
// slug категории (см. supabase/migrations/0003_categories.sql) маркерам МЕСТО.
const MARKER_BY_SLUG: Record<string, string> = {
  training: "/brand/markers/marker-workout.svg",
  cinema: "/brand/markers/marker-movie.svg",
  coffee: "/brand/markers/marker-coffee.svg",
  breakfast: "/brand/markers/marker-breakfast.svg",
  dinner: "/brand/markers/marker-dinner.svg",
  walk: "/brand/markers/marker-walk.svg",
  custom: "/brand/markers/marker-custom.svg",
};
const FALLBACK_MARKER = "/brand/markers/marker-custom.svg";
const MARKER_ASPECT = 288 / 256; // высота/ширина viewBox маркера
// "Своё предложение" (custom) — единственный маркер, где в самом файле
// цельная растровая картинка пина с заметным пустым полем по краям (у
// остальных категорий — векторный пин почти без полей + маленькая
// иконка внутри). При одинаковой рамке видимая часть пина у custom
// заметно мельче — компенсируем увеличенным размером именно для него.
const CUSTOM_MARKER_SCALE = 1.35;

/**
 * Круглый счётчик встреч — из пакета MESTO_MAP_CLUSTERS (cluster.css/.js):
 * белый круг, тёмная жирная цифра, фиолетово-оранжевая градиентная рамка,
 * мягкая тень. 52px обычно, 60px для трёх символов ("99+"). Инлайновые
 * стили вместо отдельного .css-класса — тот же подход, что уже
 * используется для остальных маркеров карты (el.style.cssText).
 */
function createClusterButton(count: number, onClick: () => void): HTMLButtonElement {
  const label = count > 99 ? "99+" : String(count);
  const isThreeChars = label.length >= 3;
  const size = isThreeChars ? 50 : 42;

  const button = document.createElement("button");
  button.type = "button";
  button.textContent = label;
  button.setAttribute("aria-label", `Показать встречи: ${count}`);
  button.style.cssText = `
    box-sizing:border-box;width:${size}px;height:${size}px;border:3px solid transparent;
    border-radius:50%;
    background:linear-gradient(#fff,#fff) padding-box,linear-gradient(135deg,#6c3bff,#8a5cff 45%,#ff8a2a) border-box;
    color:#111;font:800 ${isThreeChars ? 16 : 17}px/1 var(--font-onest),Onest,Arial,sans-serif;
    display:flex;align-items:center;justify-content:center;
    box-shadow:0 4px 12px rgba(108,59,255,0.15);cursor:pointer;padding:0;
  `.replace(/\s+/g, " ");
  button.addEventListener("click", (event) => {
    event.stopPropagation();
    onClick();
  });
  return button;
}

/**
 * Встречи с буквально одинаковыми координатами технически "раздвигаются"
 * по маленькому кругу (см. JITTER_METERS) — так стандартная пиксельная
 * кластеризация сама решает, показывать ли их одним кружком (на обычном
 * масштабе) или отдельными значками (при сильном увеличении), вместо
 * жёсткого правила "одно и то же место — всегда один кружок навсегда".
 */
function jitterExactDuplicates(events: MapEventItem[]): MapEventItem[] {
  const groups = new Map<string, MapEventItem[]>();
  for (const event of events) {
    const key = `${event.latitude.toFixed(EXACT_MATCH_PRECISION)},${event.longitude.toFixed(EXACT_MATCH_PRECISION)}`;
    const list = groups.get(key) ?? [];
    list.push(event);
    groups.set(key, list);
  }

  const result: MapEventItem[] = [];
  for (const list of groups.values()) {
    const first = list.find(() => true);
    if (!first || list.length === 1) {
      if (first) result.push(first);
      continue;
    }
    const metersPerDegreeLng = METERS_PER_DEGREE_LAT * Math.cos((first.latitude * Math.PI) / 180);
    list.forEach((event, i) => {
      const angle = (2 * Math.PI * i) / list.length;
      const dLat = (JITTER_METERS * Math.sin(angle)) / METERS_PER_DEGREE_LAT;
      const dLng = (JITTER_METERS * Math.cos(angle)) / metersPerDegreeLng;
      result.push({ ...event, latitude: event.latitude + dLat, longitude: event.longitude + dLng });
    });
  }
  return result;
}

export const EventsMap = forwardRef<EventsMapHandle, EventsMapProps>(function EventsMap(
  { events, onSelect, city },
  ref
) {
  const containerRef = useRef<HTMLDivElement>(null);
  const onSelectRef = useRef(onSelect);
  onSelectRef.current = onSelect;
  const mapRef = useRef<{
    setLocation: (opts: { center?: [number, number]; zoom?: number; bounds?: [[number, number], [number, number]] }) => void;
  } | null>(null);

  useImperativeHandle(ref, () => ({
    fitBounds(points) {
      if (!mapRef.current || points.length === 0) return;
      if (points.length === 1) {
        const only = points.find(() => true);
        if (only) mapRef.current.setLocation({ center: only, zoom: 16 });
        return;
      }
      const lngs = points.map((p) => p[0]);
      const lats = points.map((p) => p[1]);
      mapRef.current.setLocation({
        bounds: [
          [Math.min(...lngs), Math.min(...lats)],
          [Math.max(...lngs), Math.max(...lats)],
        ],
      });
    },
  }));

  useEffect(() => {
    let cancelled = false;
    const container = containerRef.current;
    if (!container) return;

    async function setup() {
      const ymaps3 = await loadYandexMaps();
      if (cancelled || !container) return;

      const { YMap, YMapDefaultSchemeLayer, YMapFeatureDataSource, YMapLayer, YMapMarker } = ymaps3 as unknown as {
        YMap: new (
          el: HTMLElement,
          opts: unknown
        ) => {
          addChild: (child: unknown) => unknown;
          setLocation: (opts: { center?: [number, number]; zoom?: number; bounds?: [[number, number], [number, number]] }) => void;
        };
        YMapDefaultSchemeLayer: new () => unknown;
        YMapFeatureDataSource: new (opts: { id: string }) => unknown;
        YMapLayer: new (opts: { source: string; type: string; zIndex: number }) => unknown;
        YMapMarker: new (opts: { coordinates: [number, number]; source: string }, el: HTMLElement) => unknown;
      };

      const center =
        events.length > 0
          ? ([
              events.reduce((sum, e) => sum + e.longitude, 0) / events.length,
              events.reduce((sum, e) => sum + e.latitude, 0) / events.length,
            ] as [number, number])
          : city
            ? await geocodeCityCenter(city)
            : DEFAULT_CENTER;
      if (cancelled) return;

      const map = new YMap(container, { location: { center, zoom: 12 } });
      mapRef.current = map;
      map.addChild(new YMapDefaultSchemeLayer());
      map.addChild(new YMapFeatureDataSource({ id: "events-source" }));
      map.addChild(new YMapLayer({ source: "events-source", type: "markers", zIndex: 1800 }));

      if (events.length === 0) return;

      const { YMapClusterer, clusterByGrid } = (await ymaps3.import("@yandex/ymaps3-clusterer")) as unknown as {
        YMapClusterer: new (props: Record<string, unknown>) => unknown;
        clusterByGrid: (opts: { gridSize: number }) => unknown;
      };
      if (cancelled) return;

      // Раздвигаем встречи с буквально одинаковыми координатами (см.
      // jitterExactDuplicates) — дальше обычная пиксельная кластеризация
      // сама решает, объединять их в кружок или показывать раздельно,
      // в зависимости от текущего масштаба карты.
      const jittered = jitterExactDuplicates(events);

      const features = jittered.map((event) => ({
        type: "Feature" as const,
        id: event.id,
        geometry: { coordinates: [event.longitude, event.latitude] as [number, number] },
        properties: { event },
      }));

      function markerRenderer(feature: (typeof features)[number]) {
        const event = feature.properties.event;
        const el = document.createElement("div");
        // "Для бизнеса" — отдельный, чуть более крупный значок (см. ТЗ:
        // "значком чуть больше чем другие значки, чтобы он выделялся"),
        // по нажатию так же открывает эту встречу.
        const src = event.isBusiness ? "/brand/markers/marker-business.png" : MARKER_BY_SLUG[event.category?.slug ?? ""] ?? FALLBACK_MARKER;
        const isCustom = !event.isBusiness && src === FALLBACK_MARKER;
        const width = event.isBusiness ? 60 : isCustom ? Math.round(46 * CUSTOM_MARKER_SCALE) : 46;
        const height = Math.round(width * MARKER_ASPECT);
        // "Кончик" пина в самой картинке — не у самого низа (y≈269 из 288
        // высоты viewBox), а чуть выше. Без явного сдвига библиотека карт
        // ставит ЛЕВЫЙ ВЕРХНИЙ угол элемента в точку координаты — из-за
        // этого пин визуально "съезжал" с адреса вместо того, чтобы точно
        // указывать на него своим кончиком.
        const tipRatioY = 269 / 288;
        el.style.cssText = `position:relative;width:${width}px;height:${height}px;cursor:pointer;transform:translate(-50%, -${(tipRatioY * 100).toFixed(2)}%);transform-origin:bottom center;`;
        el.innerHTML = `<img src="${src}" alt="" width="${width}" height="${height}" style="display:block;width:100%;height:100%;filter:drop-shadow(0 6px 10px rgba(90,65,150,0.25));" />`;
        el.addEventListener("click", () => onSelectRef.current([event]));
        return new YMapMarker({ coordinates: feature.geometry.coordinates, source: "events-source" }, el);
      }

      function clusterRenderer(coordinates: [number, number], clusterFeatures: typeof features) {
        // Счётчик кластера — число встреч в нём на текущем масштабе (п.2
        // задания на кластеризацию — считаем встречи, не участников).
        const allEvents = clusterFeatures.map((f) => f.properties.event);
        const el = document.createElement("div");
        // display:inline-block — обёртка сжимается по размеру кружка
        // внутри (без этого div растянулся бы на всю ширину контейнера,
        // и центрирование по проценту считалось бы неверно). translate
        // -50%/-50% — центр кружка (не левый верхний угол) точно на
        // координате.
        el.style.cssText = "display:inline-block;cursor:pointer;transform:translate(-50%, -50%);";
        const button = createClusterButton(allEvents.length, () => onSelectRef.current(allEvents));
        el.appendChild(button);
        return new YMapMarker({ coordinates, source: "events-source" }, el);
      }

      const clusterer = new YMapClusterer({
        method: clusterByGrid({ gridSize: CLUSTER_GRID_SIZE }),
        features,
        marker: markerRenderer,
        cluster: clusterRenderer,
      });

      map.addChild(clusterer);
    }

    setup();

    return () => {
      cancelled = true;
      mapRef.current = null;
      if (container) container.innerHTML = "";
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [events, city]);

  return <div ref={containerRef} className="h-full w-full" />;
});
ENDOFFILE

mkdir -p "components/paywall"
cat > "components/paywall/Paywall.tsx" << 'ENDOFFILE'
"use client";

import { useEffect, useState } from "react";
import { PlanCard } from "./PlanCard";
import { PLAN_LIMITS, FREE_APPLICATIONS_LIMIT, type Plan } from "@/lib/subscriptions/limits";
import { getTelegramWebApp } from "@/lib/telegram/webapp-client";

const FEATURES: Record<Plan, string[]> = {
  start: [
    "До 3 встреч за период",
    "Участие до 15 встреч за период",
    "1 поднятие",
    "Весь город",
    "Чат после подтверждения",
    "Группа до 4 человек",
    "Для бизнеса — группа до 40 человек",
  ],
  medium: [
    "До 15 встреч за период",
    "Участие до 30 встреч за период",
    "5 поднятий",
    "Расширенные фильтры",
    "Выделение встречи",
    "Закрытые встречи",
    "Группа до 10 человек",
    "Для бизнеса — группа до 100 человек",
    "Скрытие профиля",
  ],
  premium: [
    "Встречи без ограничений",
    "Участие без ограничений",
    "10 поднятий",
    "Выделение встречи",
    "Максимальный вес в рекомендациях",
    "Закрытые встречи",
    "Группа до 30 человек",
    "Для бизнеса — группа без ограничений",
    "Скрытие профиля",
  ],
};

interface PaywallProps {
  onActivated: () => void;
}

export function Paywall({ onActivated }: PaywallProps) {
  const [loadingCardPlan, setLoadingCardPlan] = useState<Plan | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [receiptContact, setReceiptContact] = useState<string | null | undefined>(undefined); // undefined = ещё загружаем
  const [contactPromptPlan, setContactPromptPlan] = useState<Plan | null>(null);
  const [contactDraft, setContactDraft] = useState("");

  // Оплата Telegram Stars временно скрыта из интерфейса (карта/СБП —
  // единственный видимый способ сейчас) — сам API (/api/subscriptions/create-invoice)
  // и обработка оплаты в lib/telegram/bot.ts не тронуты, можно вернуть кнопку позже.
  // onActivated (колбэк успешной оплаты) относился к Stars-потоку внутри
  // Mini App; для ЮKassa активация приходит асинхронно через вебхук, пока
  // человек на внешней странице оплаты — родительский экран сам
  // перезапрашивает статус подписки при возврате.
  void onActivated;

  useEffect(() => {
    fetch("/api/me/profile")
      .then((r) => r.json())
      .then((data) => setReceiptContact(data.receiptContact ?? null))
      .catch(() => setReceiptContact(null));
  }, []);

  async function startPayment(plan: Plan, contact?: string) {
    setLoadingCardPlan(plan);
    setError(null);

    try {
      const res = await fetch("/api/subscriptions/yookassa/create-payment", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(contact ? { plan, contact } : { plan }),
      });
      const data = await res.json();

      if (!res.ok || !data.confirmationUrl) {
        setError(
          data.error === "invalid_contact"
            ? "Введи корректный email или номер телефона."
            : "Не получилось открыть оплату. Попробуй ещё раз."
        );
        setLoadingCardPlan(null);
        return;
      }

      if (contact) setReceiptContact(contact);
      setContactPromptPlan(null);
      setContactDraft("");

      // Страница оплаты ЮKassa — не Mini App, а обычный внешний сайт,
      // открываем во встроенном браузере Telegram (openLink), а не внутри
      // самого мини-приложения. Активация подписки произойдёт по вебхуку
      // (см. app/api/webhooks/yookassa/route.ts) — когда человек вернётся
      // в приложение, статус уже должен обновиться.
      const webApp = getTelegramWebApp();
      if (webApp) {
        webApp.openLink(data.confirmationUrl);
      } else {
        window.location.href = data.confirmationUrl;
      }
      setLoadingCardPlan(null);
    } catch {
      setError("Проблема с соединением.");
      setLoadingCardPlan(null);
    }
  }

  function handleSelectCard(plan: Plan) {
    // Чек по 54-ФЗ уходит на email/телефон покупателя — спрашиваем один
    // раз, дальше используем сохранённый контакт без повторных вопросов.
    if (receiptContact) {
      startPayment(plan);
    } else {
      setError(null);
      setContactPromptPlan(plan);
    }
  }

  return (
    <div className="space-y-4 px-5 py-6">
      <div className="text-center">
        <h1 className="text-display">Выбери тариф</h1>
        <p className="mt-1 text-sm text-ink-600">Чтобы создавать встречи, нужна подписка.</p>
        <p className="mt-1 text-xs text-ink-400">
          Без подписки можно откликаться на встречи — до {FREE_APPLICATIONS_LIMIT} за период.
        </p>
        <p className="mt-2 inline-block rounded-pill bg-lavender-100 px-3 py-1 text-xs font-medium text-accent">
          Оплата картой / СБП
        </p>
      </div>

      {error && <p className="text-center text-sm text-red-600">{error}</p>}

      <PlanCard
        plan="start"
        limits={PLAN_LIMITS.start}
        features={FEATURES.start}
        loadingCard={loadingCardPlan === "start"}
        onSelectCard={handleSelectCard}
      />
      <PlanCard
        plan="medium"
        limits={PLAN_LIMITS.medium}
        features={FEATURES.medium}
        highlighted
        loadingCard={loadingCardPlan === "medium"}
        onSelectCard={handleSelectCard}
      />
      <PlanCard
        plan="premium"
        limits={PLAN_LIMITS.premium}
        features={FEATURES.premium}
        loadingCard={loadingCardPlan === "premium"}
        onSelectCard={handleSelectCard}
      />

      {contactPromptPlan && (
        <div
          className="fixed inset-0 z-50 flex flex-col justify-end bg-black/30"
          onClick={() => setContactPromptPlan(null)}
        >
          <div className="rounded-t-sheet bg-white p-5 pb-8" onClick={(e) => e.stopPropagation()}>
            <div className="mx-auto mb-4 h-1 w-10 rounded-pill bg-ink-400/30" />
            <h2 className="text-title mb-2">Куда прислать чек?</h2>
            <p className="mb-4 text-sm text-ink-600">
              По закону об онлайн-кассах чек нужно отправить на email или телефон — укажи один раз, дальше не
              будем спрашивать.
            </p>
            <input
              value={contactDraft}
              onChange={(e) => setContactDraft(e.target.value)}
              placeholder="email или телефон"
              className="w-full rounded-pill border border-lavender-200 bg-background px-4 py-3 text-base outline-none focus:border-accent"
              autoFocus
            />
            {error && <p className="mt-2 text-sm text-red-600">{error}</p>}
            <button
              onClick={() => contactPromptPlan && startPayment(contactPromptPlan, contactDraft.trim())}
              disabled={!contactDraft.trim() || loadingCardPlan !== null}
              className="mt-4 w-full rounded-pill bg-brand-gradient py-3.5 text-sm font-semibold text-white shadow-cta disabled:opacity-60"
            >
              {loadingCardPlan ? "Открываем оплату..." : "Продолжить"}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
ENDOFFILE

mkdir -p "app/(app)/events/[id]"
cat > "app/(app)/events/[id]/page.tsx" << 'ENDOFFILE'
"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import Image from "next/image";
import { ApplicantCard, type ApplicantCardData } from "@/components/applications/ApplicantCard";

interface EventDetails {
  id: string;
  title: string;
  description: string | null;
  category: { slug: string; name: string; emoji: string | null } | null;
  trainingType: { slug: string; name: string; emoji: string | null } | null;
  placeName: string | null;
  address: string | null;
  eventDate: string;
  eventTime: string;
  eventEndTime: string | null;
  seatsTotal: number;
  seatsTaken: number;
  status: string;
  costType: string | null;
  isBusiness: boolean;
  businessPricingType: "ticket" | "free" | "custom" | null;
  businessPricingDetails: string | null;
  organizer: {
    id: string;
    name: string;
    avatarUrl: string | null;
    age: number;
    ratingAvg: number;
    completedMeetingsCount: number;
  } | null;
  participants: { id: string; name: string; avatarUrl: string | null }[];
  viewerStatus: "organizer" | "accepted" | "pending" | "rejected" | "none";
}

interface EventDetailsPageProps {
  // Next.js 14 (в этом проекте) — params плоский объект, НЕ Promise.
  // См. пояснение в app/chats/[id]/page.tsx про баг с use(params).
  params: { id: string };
}

const CATEGORY_ICON: Record<string, string> = {
  training: "/brand/3d/workout.png",
  cinema: "/brand/3d/movie.png",
  coffee: "/brand/3d/coffee.png",
  breakfast: "/brand/3d/breakfast.png",
  dinner: "/brand/3d/dinner.png",
  walk: "/brand/3d/walk.png",
  custom: "/brand/3d/custom-proposal.png",
};

export default function EventDetailsPage({ params }: EventDetailsPageProps) {
  const { id: eventId } = params;
  const router = useRouter();

  const [event, setEvent] = useState<EventDetails | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [applying, setApplying] = useState(false);
  const [cancelling, setCancelling] = useState(false);
  const [confirmingCancel, setConfirmingCancel] = useState(false);
  const [boosting, setBoosting] = useState(false);
  const [boostMessage, setBoostMessage] = useState<string | null>(null);
  const [pendingApplicants, setPendingApplicants] = useState<ApplicantCardData[]>([]);
  const [processingApplicantId, setProcessingApplicantId] = useState<string | null>(null);

  useEffect(() => {
    fetch(`/api/events/${eventId}`)
      .then((r) => r.json())
      .then((data) => {
        if (data.error) {
          setError("Встреча не найдена.");
          return;
        }
        setEvent(data);
        // Заявки на СВОЮ встречу показываем прямо здесь, сразу как только
        // организатор открыл событие — не нужно проваливаться ещё на один
        // экран "Управлять заявками", чтобы увидеть и принять новых людей.
        if (data.viewerStatus === "organizer") {
          loadPendingApplicants();
        }
      })
      .finally(() => setLoading(false));
  }, [eventId]);

  function loadPendingApplicants() {
    fetch(`/api/events/${eventId}/applications`)
      .then((r) => r.json())
      .then((data) => {
        const items = (data.applications ?? []) as ApplicantCardData[];
        setPendingApplicants(items.filter((a) => a.status === "pending"));
      })
      .catch(() => {});
  }

  async function handleApplicantDecision(applicationId: string, action: "accept" | "reject") {
    setProcessingApplicantId(applicationId);
    try {
      const res = await fetch(`/api/applications/${applicationId}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ action }),
      });
      if (res.ok) {
        loadPendingApplicants();
        // Обновляем и саму встречу — seatsTaken и статус (могла закрыться,
        // если это было последнее место).
        fetch(`/api/events/${eventId}`)
          .then((r) => r.json())
          .then((data) => !data.error && setEvent(data));
      }
    } finally {
      setProcessingApplicantId(null);
    }
  }

  async function handleApply() {
    setApplying(true);
    try {
      const res = await fetch("/api/applications", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ eventId }),
      });
      const data = await res.json();
      if (!res.ok) {
        setError(
          data.error === "event_full"
            ? "Мест больше нет."
            : data.error === "cannot_apply_to_own_event"
              ? "Это твоя собственная встреча."
              : data.error === "applications_limit_reached"
                ? "Лимит откликов на встречи по твоему тарифу исчерпан за этот период — загляни в раздел «Подписка», чтобы поднять лимит."
                : "Не получилось отправить отклик."
        );
        return;
      }
      setEvent((prev) => (prev ? { ...prev, viewerStatus: "pending" } : prev));
    } finally {
      setApplying(false);
    }
  }

  async function handleCancel() {
    setCancelling(true);
    try {
      const res = await fetch(`/api/events/${eventId}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ action: "cancel" }),
      });
      if (res.ok) {
        setEvent((prev) => (prev ? { ...prev, status: "cancelled" } : prev));
        setConfirmingCancel(false);
      } else {
        setError("Не получилось отменить встречу.");
      }
    } finally {
      setCancelling(false);
    }
  }

  async function handleBoost() {
    setBoosting(true);
    setBoostMessage(null);
    try {
      const res = await fetch("/api/boosts", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ eventId }),
      });
      const data = await res.json();
      if (!res.ok) {
        setBoostMessage(
          data.error === "subscription_required"
            ? "Нужна подписка, чтобы поднимать встречи."
            : data.error === "boost_limit_reached"
              ? "Лимит подъёмов на этот месяц исчерпан."
              : "Не получилось поднять встречу."
        );
        return;
      }
      setBoostMessage(
        data.boostsLimit != null
          ? `Встреча поднята! Использовано ${data.boostsUsed} из ${data.boostsLimit} в этом месяце.`
          : "Встреча поднята!"
      );
    } finally {
      setBoosting(false);
      setTimeout(() => setBoostMessage(null), 4000);
    }
  }

  if (loading) {
    return (
      <div className="flex min-h-[60vh] items-center justify-center">
        <p className="text-ink-600">Загрузка...</p>
      </div>
    );
  }

  if (error && !event) {
    return (
      <div className="flex min-h-[60vh] flex-col items-center justify-center gap-3 px-6 text-center">
        <p className="text-sm text-red-600">{error}</p>
        <Link href="/feed" className="text-sm font-medium text-accent">
          Вернуться на главную
        </Link>
      </div>
    );
  }
  if (!event) return null;

  const categoryLabel = event.trainingType?.name ?? event.category?.name;
  const categoryIcon = event.category ? CATEGORY_ICON[event.category.slug] : undefined;
  const seatsLeft = event.seatsTotal - event.seatsTaken;
  const isFull = seatsLeft <= 0;

  return (
    <div className="pb-28">
      <div className="flex items-center gap-3 px-5 pt-4">
        <button onClick={() => router.back()} aria-label="Назад">
          <Image src="/brand/icons/back.svg" alt="" width={22} height={22} />
        </button>
      </div>

      <div className="px-5 pt-4">
        <div className="mb-2 flex items-center gap-1.5 text-sm font-medium text-accent">
          {categoryIcon ? (
            <div className="relative h-5 w-5 shrink-0">
              <Image src={categoryIcon} alt="" fill className="object-contain" sizes="20px" />
            </div>
          ) : (
            <span>{event.category?.emoji}</span>
          )}
          <span>{categoryLabel}</span>
        </div>

        <h1 className="text-display mb-3">{event.title}</h1>

        <div className="mb-4 space-y-1.5 text-sm text-ink-600">
          <p>
            {formatDate(event.eventDate)} ·{" "}
            {event.eventEndTime
              ? `${event.eventTime.slice(0, 5)}–${event.eventEndTime.slice(0, 5)}`
              : event.eventTime.slice(0, 5)}
          </p>
          {event.placeName && (
            <p>
              {event.placeName}
              {event.address ? `, ${event.address}` : ""}
            </p>
          )}
          <p>{isFull ? "Мест нет" : `Свободно мест: ${seatsLeft} из ${event.seatsTotal}`}</p>
          {event.isBusiness && (
            <p>
              {event.businessPricingType === "ticket"
                ? `Билет: ${event.businessPricingDetails}`
                : event.businessPricingType === "custom"
                  ? event.businessPricingDetails
                  : "Бесплатно"}
            </p>
          )}
        </div>

        {event.participants.length > 0 && (
          <div className="mb-4 flex items-center gap-2">
            <div className="flex -space-x-2">
              {event.participants.slice(0, 5).map((p) => (
                <div
                  key={p.id}
                  className="flex h-8 w-8 items-center justify-center overflow-hidden rounded-full border-2 border-white bg-lavender-100 text-xs font-semibold text-ink-600"
                >
                  {p.avatarUrl ? (
                    // eslint-disable-next-line @next/next/no-img-element
                    <img src={p.avatarUrl} alt={p.name} className="h-full w-full object-cover" />
                  ) : (
                    p.name.charAt(0).toUpperCase()
                  )}
                </div>
              ))}
            </div>
            <span className="text-xs text-ink-600">
              {event.participants.length} {pluralizeParticipants(event.participants.length)}
            </span>
          </div>
        )}

        {event.description && <p className="mb-5 text-sm text-ink-900">{event.description}</p>}

        {event.organizer && (
          <div className="mb-5 flex items-center gap-3 rounded-card bg-white p-4 shadow-card">
            <div className="flex h-11 w-11 items-center justify-center overflow-hidden rounded-full bg-background text-sm font-semibold text-ink-600">
              {event.organizer.avatarUrl ? (
                // eslint-disable-next-line @next/next/no-img-element
                <img src={event.organizer.avatarUrl} alt={event.organizer.name} className="h-full w-full object-cover" />
              ) : (
                event.organizer.name.charAt(0).toUpperCase()
              )}
            </div>
            <div className="min-w-0 flex-1">
              <p className="text-sm font-medium text-ink-900">
                {event.organizer.name}, {event.organizer.age}
              </p>
              <p className="text-xs text-ink-600">
                {event.organizer.ratingAvg > 0 ? `⭐ ${event.organizer.ratingAvg.toFixed(1)} · ` : ""}
                {event.organizer.completedMeetingsCount} встреч проведено
              </p>
            </div>
          </div>
        )}

        {error && <p className="mb-3 text-center text-sm text-red-600">{error}</p>}

        {event.status === "cancelled" && (
          <div className="mb-3 rounded-card bg-red-50 p-4 text-center text-sm text-red-600">
            Эта встреча отменена организатором.
          </div>
        )}

        {event.viewerStatus === "organizer" &&
          (event.status === "published" || event.status === "closed") && (
          <div className="mb-3 space-y-3">
            {event.status === "published" && pendingApplicants.length > 0 && (
              <div className="rounded-card bg-white p-4 shadow-card">
                <h3 className="mb-3 text-sm font-semibold text-ink-900">
                  Новые заявки ({pendingApplicants.length})
                </h3>
                <div className="space-y-3">
                  {pendingApplicants.map((app) => (
                    <ApplicantCard
                      key={app.id}
                      application={app}
                      onAccept={(id) => handleApplicantDecision(id, "accept")}
                      onReject={(id) => handleApplicantDecision(id, "reject")}
                      processing={processingApplicantId === app.id}
                    />
                  ))}
                </div>
              </div>
            )}

            {/* "Поднять встречу" имеет смысл только пока идёт набор — для
                забитой (closed) встречи мест всё равно нет. */}
            {event.status === "published" && (
              <>
                <button
                  onClick={handleBoost}
                  disabled={boosting}
                  className="flex w-full items-center justify-center gap-2 rounded-pill bg-brand-gradient py-3 text-sm font-semibold text-white shadow-cta disabled:opacity-60"
                >
                  <span className="text-lg">🚀</span>
                  {boosting ? "Поднимаем..." : "Поднять встречу"}
                </button>
                {boostMessage && <p className="text-center text-xs text-ink-600">{boostMessage}</p>}
              </>
            )}

            {/* Отменить встречу — доступно и для забитой (closed) встречи,
                не только для той, что ещё набирает участников. */}
            {!confirmingCancel ? (
              <button
                onClick={() => setConfirmingCancel(true)}
                className="w-full text-center text-sm font-medium text-red-600"
              >
                Отменить встречу
              </button>
            ) : (
              <div className="rounded-card bg-red-50 p-4 text-center">
                <p className="mb-3 text-sm text-ink-900">Точно отменить встречу? Лимит тарифа вернётся.</p>
                <div className="flex gap-2">
                  <button
                    onClick={() => setConfirmingCancel(false)}
                    className="flex-1 rounded-pill bg-white py-2.5 text-sm font-medium text-ink-600 shadow-card"
                  >
                    Не отменять
                  </button>
                  <button
                    onClick={handleCancel}
                    disabled={cancelling}
                    className="flex-1 rounded-pill bg-red-600 py-2.5 text-sm font-semibold text-white disabled:opacity-50"
                  >
                    {cancelling ? "Отменяем..." : "Да, отменить"}
                  </button>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* Кнопка "Управлять заявками" (единственный путь к удалению
          участника организатором) — тоже нужна и для забитой (closed)
          встречи, не только для набирающей участников. */}
      {(event.status === "published" || event.status === "closed") && (
        <div className="fixed inset-x-0 bottom-24 z-40 px-5">
          <BottomAction
            viewerStatus={event.viewerStatus}
            isFull={isFull}
            applying={applying}
            onApply={handleApply}
            eventId={event.id}
          />
        </div>
      )}
    </div>
  );
}

function BottomAction({
  viewerStatus,
  isFull,
  applying,
  onApply,
  eventId,
}: {
  viewerStatus: EventDetails["viewerStatus"];
  isFull: boolean;
  applying: boolean;
  onApply: () => void;
  eventId: string;
}) {
  if (viewerStatus === "organizer") {
    return (
      <Link
        href={`/events/${eventId}/applications`}
        className="block w-full rounded-pill bg-brand-gradient py-4 text-center text-base font-semibold text-white shadow-cta"
      >
        Управлять заявками
      </Link>
    );
  }
  if (viewerStatus === "accepted") {
    return (
      <div className="w-full rounded-pill bg-ink-900 py-4 text-center text-base font-semibold text-white">
        Ты идёшь ✓
      </div>
    );
  }
  if (viewerStatus === "pending") {
    return (
      <div className="w-full rounded-pill bg-ink-400/10 py-4 text-center text-base font-semibold text-ink-600">
        Отклик отправлен
      </div>
    );
  }
  if (viewerStatus === "rejected") {
    return (
      <div className="w-full rounded-pill bg-ink-400/10 py-4 text-center text-base font-semibold text-ink-400">
        Отклонено
      </div>
    );
  }

  return (
    <button
      onClick={onApply}
      disabled={isFull || applying}
      className="w-full rounded-pill bg-brand-gradient py-4 text-base font-semibold text-white shadow-cta disabled:opacity-40"
    >
      {isFull ? "Мест нет" : applying ? "Отправляем..." : "Я иду"}
    </button>
  );
}

function formatDate(dateIso: string): string {
  return new Date(dateIso).toLocaleDateString("ru-RU", { day: "numeric", month: "long" });
}

function pluralizeParticipants(count: number): string {
  const mod10 = count % 10;
  const mod100 = count % 100;
  if (mod10 === 1 && mod100 !== 11) return "человек идёт";
  if ([2, 3, 4].includes(mod10) && ![12, 13, 14].includes(mod100)) return "человека идут";
  return "человек идут";
}
ENDOFFILE

